import csv, io
cases = [
 dict(delimiter=""), dict(delimiter="ab"), dict(delimiter=1), dict(delimiter=None),
 dict(quotechar=""), dict(quotechar="ab"), dict(quotechar=1), dict(quotechar=None),
 dict(quotechar=None, quoting=0), dict(quotechar=None, quoting=3),
 dict(escapechar=""), dict(escapechar="ab"), dict(escapechar=1),
 dict(lineterminator=1), dict(lineterminator=None), dict(lineterminator=""),
 dict(quoting=-1), dict(quoting=4), dict(quoting=True), dict(quoting=1.0),
 dict(doublequote=None), dict(skipinitialspace=1), dict(strict=1),
 dict(delimiter=","), dict(delimiter="\n"), dict(quotechar="a"),
 dict(delimiter="\t"), dict(quotechar="\\", escapechar="\\"),
]
for i,c in enumerate(cases):
