import csv, io
rows = [
 [], [""], ["",""], [None], [None,None], ["a"], ["a,b"], ['a"b'], ["a\nb"],
 ["a\rb"], ["a\r\nb"], ["a\\b"], ["|"], [1], [2.5], [True], [False], [0],
 [-0.0], [1e300], [10**30], [[1,2]], [{"a":1}], [(1,2)], ["  a  "],
 ["a"*3], ["\t"], ['"'], ['""'], ["\\"], ["a", 1, None, 2.5, "b,c"],
 ["å"], [b"x"], [range(2)],
]
ds=[]
for q in (0,1,2,3):
    for esc in (None,"\\"):
        for dq in (True,False):
            for delim in (",","|"):
                for qc in ('"',"'"):
                    for lt in ("\r\n","\n","|"):
                        ds.append(dict(quoting=q,escapechar=esc,doublequote=dq,
                                       delimiter=delim,quotechar=qc,lineterminator=lt))
n=0
for di,d in enumerate(ds):
    for ri,r in enumerate(rows):
        n+=1
        o=io.StringIO()
        try:
            w=csv.writer(o,**d)
            rc=w.writerow(r)
            res=repr(o.getvalue())+"|"+str(rc)
        except Exception as e:
            res="EXC "+type(e).__name__+": "+str(e)
        print(di,ri,res)
print("N",n)

import csv, io
inputs=["", "a,b\n", "a,b\n1,2\n", "a,b\n1,2,3\n", "a,b\n1\n", "a,b\n\n1,2\n",
        "a,b\n\n\n", "\n", "a,b\r\n1,2\r\n", 'a,b\n"x\ny",2\n']
fns=[None, ["p","q"], ["p"], []]
rks=[None,"REST"]; rvs=[None,"RV"]
n=0
for ii,s in enumerate(inputs):
    for fi,fn in enumerate(fns):
        for ki,rk in enumerate(rks):
            for vi,rv in enumerate(rvs):
                n+=1
                try:
                    dr=csv.DictReader(io.StringIO(s),fieldnames=fn,restkey=rk,restval=rv)
                    out=[]
                    for row in dr: out.append(sorted(row.items(), key=lambda kv: str(kv[0])))
                    res=repr(out)+"|ln="+str(dr.line_num)+"|fn="+repr(dr.fieldnames)
                except Exception as e:
                    res="EXC "+type(e).__name__+": "+str(e)
                print("R",ii,fi,ki,vi,res)
